/// <summary>
/// Determines if concurrent deletes should throw exception.
/// </summary>
/// <returns>true, if exception should be thrown; otherwise, false.</returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    return true;
}

public static boolean exist(FTDId _id)
{
    return (select firstonly RecId from FTDBookTable
        where FTDBookTable.Id == _id).RecId != 0;
}

public static FTDBookTable find(FTDId _id)
{
    FTDBookTable bookTable;

    select firstonly bookTable
        where bookTable.Id == _id;

    return bookTable;
}

public static FTDBookTable findRecId(RecId _recId)
{
    FTDBookTable bookTable;

    select firstonly bookTable
        where bookTable.RecId == _recId;

    return bookTable;
}

public static int selectCountByGenre(FTDGenreEnum _genre)
{
    FTDBookTable bookTable;

    select count(RecId) from bookTable
        group by Genre
        where bookTable.Genre == _genre;

    return bookTable.RecId;
}

[SysClientCacheDataMethod(true)]
public display FTDAuthorFullName dispAuthorFullName()
{
    FTDAuthorTable authorTable = FTDAuthorTable::findRecId(this.Author);

    return authorTable.FirstName + ' ' + authorTable.LastName;
}

[SysClientCacheDataMethod(true)]
public display FTDInventoryQty dispCurrentInventory()
{
    return this.currentInventory();
}

public Qty currentInventory(RecId _excludeTransactionRecId = 0)
{
    FTDBookInventoryTransaction transactions;

    select sum(Qty) from transactions
        where transactions.Book == this.RecId
        && transactions.RecId != _excludeTransactionRecId;

    return transactions.Qty;
}

public Common AuthorTableLookup(FormReferenceControl _formReferenceControl)
{
    SysReferenceTableLookup refTableLookup = SysReferenceTableLookup::newParameters(tableNum(FTDAuthorTable), _formReferenceControl);

    refTableLookup.parmQuery(this.getLookupQuery());
    refTableLookup.addLookupfield(fieldNum(FTDAuthorTable, Id));
    refTableLookup.addLookupfield(fieldNum(FTDAuthorTable, FirstName));
    refTableLookup.addLookupfield(fieldNum(FTDAuthorTable, LastName));
    refTableLookup.addLookupfield(fieldNum(FTDAuthorTable, IsDead));

    return refTableLookup.performFormLookup();
}

private Query getLookupQuery()
{
    Query               q = new Query();
    QuerybuildDataSource qbds = q.addDataSource(tableNum(FTDAuthorTable));

    qbds.addRange(fieldNum(FTDAuthorTable, IsDead)).value(queryValue(NoYes::No));

    return q;
}
